const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const latitude = 34.498828;
  const longitude = -112.246886;
  const point = ee.Geometry.Point(longitude, latitude);
  const bufferRadiusMiles = 50;
  const bufferRadiusMeters = bufferRadiusMiles * 1609.34; // Convert miles to meters
  const geometry = point.buffer(bufferRadiusMeters);

  const startDate = '2017-06-20';
  const endDate = '2017-06-30';

  // 2. Data Acquisition & Check
  const modisFires = ee.ImageCollection('MODIS/006/MCD14ML')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  const collectionSize = await modisFires.size().getInfo();

  if (collectionSize === 0) {
    console.log("No MODIS fire data found for the specified date range and location.");
    console.log("C1");
    return;
  }

  // 3. Processing: Identify high-confidence fire pixels
  // The 'confidence' band ranges from 0-100. Values >= 60 are generally considered high confidence fires.
  const highConfidenceFires = modisFires.map(image =>
    image.select('confidence').gte(60).rename('fire_pixel')
  );

  // Combine all fire observations into a single image where 1 indicates fire at any time during the period.
  const fireOccurrence = highConfidenceFires.max();

  // Calculate the sum of fire pixels within the buffered region.
  // Using a larger scale (e.g., 1000m) for MODIS data to avoid excessive computation.
  const firePixelCount = await fireOccurrence.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000, // MODIS fire pixels are 1km
    maxPixels: 1e9
  }).get('fire_pixel').getInfo();

  if (firePixelCount === null) {
    console.log("Calculation failed to return a valid pixel count (likely null).");
    console.log("C3");
    return;
  }

  // 4. Validation & Final Answer
  const validPixelCount = await fireOccurrence.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('fire_pixel').getInfo();

  if (validPixelCount === 0) {
    console.log("No valid pixels remain after processing (e.g., area entirely masked or outside data extent).");
    console.log("C2");
    return;
  }

  console.log(`MODIS Images: ${collectionSize}`);
  console.log(`Total high-confidence fire pixels detected: ${firePixelCount}`);

  if (firePixelCount > 0) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
